using System.Net;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text.Json;
using EduForge.Domain;
using EduForge.Infrastructure;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Xunit;
namespace EduForge.Tests;
public class AssignmentRecoveryTests {
 static async Task Login(HttpClient c,string email){var r=await c.PostAsJsonAsync("/api/auth/register",new{email,name="QA",password="Original password long enough!"});r.EnsureSuccessStatusCode();c.DefaultRequestHeaders.Add("Cookie",r.Headers.GetValues("Set-Cookie").Single().Split(';')[0]);}
 [Fact] public async Task AssignmentHidesTestsAndChecksGradingOwnershipAndBounds(){using var f=new ApiFactory();using var owner=f.Browser();using var other=f.Browser();using var student=f.Browser();await Login(owner,"teacher@example.test");await Login(other,"other@example.test");var r=await owner.PostAsJsonAsync("/api/assignments",new{title="Макет",description="Нарисовать",kind="Design",maxScore=40,tests=new[]{new{input="hidden",expected="secret"}},rubric="Композиция"});r.EnsureSuccessStatusCode();var a=await r.Content.ReadFromJsonAsync<JsonElement>();var id=a.GetProperty("id").GetString();var token=a.GetProperty("token").GetString();var task=await student.GetAsync("/api/tasks/"+token);Assert.DoesNotContain("secret",await task.Content.ReadAsStringAsync());var submit=await student.PostAsJsonAsync("/api/tasks/"+token+"/submit",new{name="Студент",content="Моя работа",attachment="https://example.test/work"});submit.EnsureSuccessStatusCode();Assert.Equal(HttpStatusCode.NotFound,(await other.GetAsync($"/api/assignments/{id}/submissions")).StatusCode);var works=await owner.GetFromJsonAsync<JsonElement[]>($"/api/assignments/{id}/submissions");var sid=works![0].GetProperty("id").GetString();Assert.Equal(HttpStatusCode.BadRequest,(await owner.PostAsJsonAsync($"/api/assignments/{id}/submissions/{sid}/grade",new{score=41,feedback=""})).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await other.PostAsJsonAsync($"/api/assignments/{id}/submissions/{sid}/grade",new{score=20,feedback=""})).StatusCode);Assert.Equal(HttpStatusCode.NoContent,(await owner.PostAsJsonAsync($"/api/assignments/{id}/submissions/{sid}/grade",new{score=35,feedback="Хорошая композиция"})).StatusCode);}
 [Fact] public async Task ResetIsSingleUseAndRevokesExistingSession(){using var f=new ApiFactory();using var c=f.Browser();await Login(c,"reset@example.test");var token=new string('A',64);using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<MaterialDbContext>();var teacher=await db.Teachers.SingleAsync();db.PasswordResets.Add(new PasswordReset{TeacherId=teacher.Id,Hash=Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(token))),ExpiresAt=DateTimeOffset.UtcNow.AddMinutes(10).ToUnixTimeMilliseconds()});await db.SaveChangesAsync();}var reset=new{token,password="New password is long enough!"};Assert.Equal(HttpStatusCode.NoContent,(await c.PostAsJsonAsync("/api/auth/reset",reset)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/auth/me")).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsJsonAsync("/api/auth/reset",reset)).StatusCode);Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync("/api/auth/login",new{email="reset@example.test",password=reset.password})).StatusCode);}
 [Fact] public async Task CopiedImagesSurviveDeletionOfOriginalAuthor(){using var f=new ApiFactory{AdminEmail="admin@example.test"};using var author=f.Browser();using var copyOwner=f.Browser();using var admin=f.Browser();await Login(author,"author@example.test");await Login(copyOwner,"copy@example.test");await Login(admin,"admin@example.test");using var form=new MultipartFormDataContent();form.Add(new ByteArrayContent(new byte[]{137,80,78,71,13,10,26,10}),"file","sample.png");var upload=await author.PostAsync("/api/media",form);upload.EnsureSuccessStatusCode();var url=(await upload.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("url").GetString();var r=await author.PostAsJsonAsync("/api/materials",new{title="Иллюстрация",subject="Дизайн",content="Изображение "+url});var id=(await r.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetString();(await author.PostAsync($"/api/materials/{id}/publication",null)).EnsureSuccessStatusCode();var copyResponse=await copyOwner.PostAsync($"/api/library/{id}/copy",null);var copy=(await copyResponse.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetString();var material=await copyOwner.GetFromJsonAsync<JsonElement>("/api/materials/"+copy);var copiedUrl=material.GetProperty("content").GetString()!.Split(' ').Last();Assert.NotEqual(url,copiedUrl);using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<MaterialDbContext>();var teacher=await db.Teachers.SingleAsync(x=>x.Email=="author@example.test");Assert.Equal(HttpStatusCode.NoContent,(await admin.DeleteAsync($"/api/admin/users/{teacher.Id}?deleteData=true")).StatusCode);}Assert.Equal(HttpStatusCode.OK,(await copyOwner.GetAsync(copiedUrl)).StatusCode);}
}
